// Cartwheel's five order statuses come from the orders table.
type OrderStatus = 'processing' | 'shipped' | 'delivered' | 'cancelled' | 'returned';

const statusLabels: Record<OrderStatus, string> = {
  processing: 'Processing',
  shipped: 'Shipped',
  delivered: 'Delivered',
  cancelled: 'Cancelled',
  returned: 'Returned',
};

function statusLabel(status: OrderStatus): string {
  return statusLabels[status];
}

function canCancel(status: OrderStatus): boolean {
  return status === 'processing';
}

// ---- Type tests (do not edit) ----
type T1 = Expect<Equal<OrderStatus, 'processing' | 'shipped' | 'delivered' | 'cancelled' | 'returned'>>;

// @ts-expect-error: 'canceled' (one L) is a typo, not a status
